"use client";

import * as React from "react";
interface AiAnswerCleanProps {
  question?: string;
  sources: AnswerSource[];
  answer: string;
  streaming?: boolean;
  animate?: boolean;
  speed?: number;
  followUps?: string[];
  onFollowUp?: (question: string) => void;
  onRegenerate?: () => void;
  onStop?: () => void;
  onFeedback?: (value: "up" | "down", reason?: string) => void;
  feedbackReasons?: string[];
  onCopy?: (text: string) => void;
  className?: string;
}
type AnswerSource = {
  name: string;
  title: string;
  href: string;
  icon: React.ReactNode;
  snippet: string;
} & {
  id?: string;
  url?: string;
  domain?: string;
  description?: string;
};
type AnswerBlock =
  | {
      kind: "p";
      tokens: AnswerToken[];
    }
  | {
      kind: "ul";
      items: AnswerToken[][];
    };
type AnswerToken =
  | {
      i: number;
      kind: "word";
      text: string;
      bold: boolean;
    }
  | {
      i: number;
      kind: "cite";
      ids: number[];
    };
function parseCleanAnswer(answer: string, sourceCount: number) {
  let nextTokenIndex = 0,
    parseInline = (text: string) => {
      let tokens: AnswerToken[] = [];
      for (let i of text.split(/(\*\*[^*]+\*\*|\[\d+(?:\s*,\s*\d+)*\])/)) {
        if (!i) continue;
        let e = i.match(/^\[([\d,\s]+)\]$/);
        if (e) {
          let i = e[1]
            .split(`,`)
            .map((e) => Number(e) - 1)
            .filter((e) => e >= 0 && e < sourceCount);
          if (!i.length) continue;
          let a = tokens[tokens.length - 1];
          a?.kind === `cite`
            ? (a.ids = [...new Set([...a.ids, ...i])])
            : tokens.push({
                i: nextTokenIndex++,
                kind: `cite`,
                ids: i,
              });
          continue;
        }
        let a = i.startsWith(`**`);
        for (let e of (a ? i.slice(2, -2) : i).match(/\S+\s*|\s+/g) ?? []) {
          let t = tokens[tokens.length - 1];
          if (!e.trim()) {
            t?.kind === `word` && (t.text += e);
            continue;
          }
          tokens.push({
            i: nextTokenIndex++,
            kind: `word`,
            text: e,
            bold: a,
          });
        }
      }
      return tokens;
    },
    blocks: AnswerBlock[] = [];
  for (let t of answer.split(/\n\s*\n/)) {
    let e = t
      .split(
        `
`,
      )
      .filter((e) => e.trim());
    e.length &&
      (e.every((e) => /^\s*[-*]\s/.test(e))
        ? blocks.push({
            kind: `ul`,
            items: e.map((e) => parseInline(e.replace(/^\s*[-*]\s/, ``))),
          })
        : blocks.push({
            kind: `p`,
            tokens: parseInline(e.join(` `)),
          }));
  }
  return {
    blocks: blocks,
    total: nextTokenIndex,
  };
}
function formatCleanAnswerForCopy(answer: string, sources: AnswerSource[]) {
  let plainText = answer
    .replace(/\*\*([^*]+)\*\*/g, `$1`)
    .replace(/\s*\[(\d+(?:\s*,\s*\d+)*)\]/g, (e, t) => ` [${t.replace(/\s/g, ``)}]`)
    .trim();
  return sources.length
    ? `${plainText}\n\nSources:\n${sources.map(
        (e, t) => `[${t + 1}] ${e.title}${e.href ? ` – ${e.href}` : ``}`,
      ).join(`
`)}`
    : plainText;
}
var CleanAnswerIcon = ({
  d: path,
  solid: solid,
  className: className,
}: {
  d: string;
  solid?: boolean;
  className?: string | undefined;
}) => (
  <svg
    viewBox={`0 0 16 16`}
    className={[`ui-ansc__glyph`, className].filter(Boolean).join(` `)}
    data-solid={solid || void 0}
    aria-hidden={`true`}
  >
    <path d={path} />
  </svg>
);
var iconPaths = {
  copy: `M5.5 2A1.5 1.5 0 0 0 4 3.5V4h5A3 3 0 0 1 12 7v5h.5a1.5 1.5 0 0 0 1.5-1.5v-7A1.5 1.5 0 0 0 12.5 2h-7ZM3.5 5A1.5 1.5 0 0 0 2 6.5v6A1.5 1.5 0 0 0 3.5 14H9a1.5 1.5 0 0 0 1.5-1.5v-6A1.5 1.5 0 0 0 9 5H3.5Z`,
  check: `M1.5 8a6.5 6.5 0 1 1 13 0 6.5 6.5 0 0 1-13 0Zm8.9-1.2a.5.5 0 0 0-.8-.6L7.44 9.23 6.35 8.15a.5.5 0 1 0-.7.7l1.5 1.5a.5.5 0 0 0 .76-.06l2.5-3.5Z`,
  redo: `M13 8a5 5 0 1 1-1.46-3.54M13 2.5v2.5h-2.5`,
  thumb: `M4.5 7v6.5H3a1 1 0 0 1-1-1V8a1 1 0 0 1 1-1h1.5Zm1 6.5h5.95a1.5 1.5 0 0 0 1.47-1.2l.86-4.3A1.5 1.5 0 0 0 12.31 6.2H9.5l.42-2.08A1.4 1.4 0 0 0 7.3 3.1L5.5 6.8v6.7Z`,
  chevron: `M10.85 7.65a.5.5 0 0 1 0 .7L7.2 12a.5.5 0 0 1-.7-.7L9.79 8 6.5 4.7a.5.5 0 1 1 .7-.7l3.65 3.65Z`,
};
function AnswerSpark() {
  return (
    <svg viewBox={`0 0 16 16`} className={`ui-ansc__mark`} aria-hidden={`true`}>
      <path
        className={`ui-ansc__mark-big`}
        d={`M6.5 2.2c.2 0 .36.14.4.33.53 2.6 1.4 3.48 4 4.02a.4.4 0 0 1 0 .79c-2.6.53-3.47 1.4-4 4a.4.4 0 0 1-.8 0c-.53-2.6-1.4-3.47-4-4a.4.4 0 0 1 0-.79c2.6-.54 3.47-1.42 4-4.02a.4.4 0 0 1 .4-.33Z`}
      />
      <path
        className={`ui-ansc__mark-small`}
        d={`M12 9.6c.12 0 .22.08.25.2.28 1.3.72 1.75 2.03 2.03a.25.25 0 0 1 0 .49c-1.31.28-1.75.72-2.03 2.03a.25.25 0 0 1-.5 0c-.28-1.31-.72-1.75-2.03-2.03a.25.25 0 0 1 0-.49c1.31-.28 1.75-.73 2.03-2.03a.25.25 0 0 1 .25-.2Z`}
      />
    </svg>
  );
}
var readingDelayMs = 700;
var sourceStaggerMs = 90;
function AiAnswerClean({
  question: question,
  sources: sources,
  answer: answer,
  streaming = false,
  animate = true,
  speed = 38,
  followUps = [],
  onFollowUp: onFollowUp,
  onRegenerate: onRegenerate,
  onStop: onStop,
  onFeedback: onFeedback,
  feedbackReasons = [`Not accurate`, `Wrong source`, `Too long`, `Out of date`],
  onCopy: onCopy,
  className: className,
}: AiAnswerCleanProps) {
  let { blocks: blocks, total: totalTokens } = React.useMemo(
      () => parseCleanAnswer(answer, sources.length),
      [answer, sources.length],
    ),
    [runId, setRunId] = React.useState(0),
    [phase, setPhase] = React.useState(`reading`),
    [visibleTokens, setVisibleTokens] = React.useState(0),
    [elapsedSeconds, setElapsedSeconds] = React.useState(0),
    [feedback, setFeedback] = React.useState<"up" | "down" | null>(null),
    [feedbackReason, setFeedbackReason] = React.useState<string | null>(null),
    [copied, setCopied] = React.useState(false),
    [popover, setPopover] = React.useState<{
      ids: number[];
      left: number;
      top: number;
      width: number;
    } | null>(null),
    [hoveredSource, setHoveredSource] = React.useState<number | null>(null),
    rootRef = React.useRef<HTMLDivElement | null>(null),
    cardRef = React.useRef<HTMLDivElement | null>(null),
    innerRef = React.useRef<HTMLDivElement | null>(null),
    tokenCursorRef = React.useRef(0),
    startedAtRef = React.useRef(0),
    previousAnswerRef = React.useRef(answer),
    hideTimerRef = React.useRef(0),
    instanceId = React.useId(),
    isFinished = phase === `done` || phase === `stopped`,
    skipAnimation = !animate || prefersReducedMotion();
  (React.useEffect(() => {
    (answer.startsWith(previousAnswerRef.current) || setRunId((e) => e + 1),
      (previousAnswerRef.current = answer));
  }, [answer]),
    React.useEffect(() => {
      if (
        ((startedAtRef.current = performance.now()),
        (tokenCursorRef.current = 0),
        setVisibleTokens(0),
        setFeedback(null),
        setFeedbackReason(null),
        setCopied(false),
        setPopover(null),
        skipAnimation)
      ) {
        ((tokenCursorRef.current = 1 / 0), setPhase(`writing`));
        return;
      }
      setPhase(`reading`);
      let e = window.setTimeout(
        () => setPhase(`writing`),
        sources.length ? readingDelayMs + sources.length * sourceStaggerMs : 0,
      );
      return () => clearTimeout(e);
    }, [runId]),
    React.useEffect(() => {
      if (phase !== `writing`) return;
      let e = 0,
        t = performance.now(),
        n = (r: number) => {
          if (
            ((tokenCursorRef.current = Math.min(
              totalTokens,
              tokenCursorRef.current + ((r - t) / 1e3) * speed,
            )),
            (t = r),
            setVisibleTokens(Math.floor(tokenCursorRef.current)),
            tokenCursorRef.current >= totalTokens && !streaming)
          ) {
            (setElapsedSeconds(
              Math.max(0.1, Math.round((performance.now() - startedAtRef.current) / 100) / 10),
            ),
              setPhase(`done`));
            return;
          }
          e = requestAnimationFrame(n);
        };
      return ((e = requestAnimationFrame(n)), () => cancelAnimationFrame(e));
    }, [phase, totalTokens, streaming, speed]),
    React.useLayoutEffect(() => {
      let e = cardRef.current,
        t = innerRef.current;
      if (!e || !t) return;
      let n = () => (e.style.height = `${t.offsetHeight}px`);
      n();
      let r = new ResizeObserver(n);
      return (r.observe(t), () => r.disconnect());
    }, []),
    React.useEffect(() => {
      if (!copied) return;
      let e = window.setTimeout(() => setCopied(false), 1800);
      return () => clearTimeout(e);
    }, [copied]));
  let openPopover = (ids: number[], target: HTMLButtonElement) => {
      clearTimeout(hideTimerRef.current);
      let root = rootRef.current;
      if (!root) return;
      let rootRect = root.getBoundingClientRect(),
        targetRect = target.getBoundingClientRect(),
        width = Math.min(300, rootRect.width - 16),
        left = Math.max(
          8,
          Math.min(
            rootRect.width - width - 8,
            targetRect.left - rootRect.left + targetRect.width / 2 - width / 2,
          ),
        );
      setPopover({
        ids: ids,
        left: left,
        top: targetRect.bottom - rootRect.top + 6,
        width: width,
      });
    },
    schedulePopoverClose: () => void = () => {
      (clearTimeout(hideTimerRef.current),
        (hideTimerRef.current = window.setTimeout(() => setPopover(null), 140)));
    },
    highlightedSources = new Set(
      popover ? popover.ids : hoveredSource === null ? [] : [hoveredSource],
    ),
    copyAnswer: React.MouseEventHandler<HTMLButtonElement> = () => {
      let plainText = formatCleanAnswerForCopy(answer, sources);
      (navigator.clipboard?.writeText(plainText).catch(() => {}),
        setCopied(true),
        onCopy?.(plainText));
    },
    stopAnswer: React.MouseEventHandler<HTMLButtonElement> = () => {
      (setElapsedSeconds(
        Math.max(0.1, Math.round((performance.now() - startedAtRef.current) / 100) / 10),
      ),
        setPhase(`stopped`),
        onStop?.());
    },
    regenerate: React.MouseEventHandler<HTMLButtonElement> = () => {
      (setRunId((e) => e + 1), onRegenerate?.());
    },
    toggleFeedback = (vote: "up" | "down") => {
      let nextVote = feedback === vote ? null : vote;
      (setFeedback(nextVote), setFeedbackReason(null), nextVote === `up` && onFeedback?.(`up`));
    },
    statusLabel = copied
      ? `Copied`
      : feedback === `up` || feedbackReason
        ? `Thanks for the feedback`
        : feedback === `down`
          ? `What went wrong?`
          : phase === `stopped`
            ? `Stopped`
            : `Answered in ${elapsedSeconds}s`,
    phaseLabel =
      phase === `reading`
        ? `Reading ${sources.length} sources`
        : phase === `writing`
          ? `Writing`
          : `Answer`,
    renderTokens = (tokens: AnswerToken[]) =>
      tokens.map((e) => {
        if (e.i >= visibleTokens) return null;
        let n =
          phase === `writing` && e.i === visibleTokens - 1 ? (
            <span className={`ui-ansc__caret`} aria-hidden={`true`} />
          ) : null;
        if (e.kind === `word`)
          return (
            <span className={`ui-ansc__w`} data-bold={e.bold || void 0} key={e.i}>
              {e.text}
              {n}
            </span>
          );
        let i = sources[e.ids[0]];
        return (
          <span className={`ui-ansc__w`} key={e.i}>
            <button
              type={`button`}
              className={`ui-ansc__cite`}
              data-lit={e.ids.some((e) => highlightedSources.has(e)) || void 0}
              aria-label={`Source: ${e.ids.map((e) => sources[e].title).join(`, `)}`}
              aria-describedby={popover && popover.ids === e.ids ? instanceId : void 0}
              onMouseEnter={(t) => openPopover(e.ids, t.currentTarget)}
              onMouseLeave={schedulePopoverClose}
              onFocus={(t) => openPopover(e.ids, t.currentTarget)}
              onBlur={schedulePopoverClose}
              onClick={(t) =>
                popover?.ids === e.ids ? setPopover(null) : openPopover(e.ids, t.currentTarget)
              }
              onKeyDown={(e) => e.key === `Escape` && setPopover(null)}
            >
              {i.name}
              {e.ids.length > 1 && (
                <span className={`ui-ansc__more`}>
                  {`+`}
                  {e.ids.length - 1}
                </span>
              )}
            </button>
            {n}
          </span>
        );
      }),
    firstTokenIndex = (block: AnswerBlock) =>
      (block.kind === `p` ? block.tokens[0]?.i : block.items[0]?.[0]?.i) ?? 1 / 0;
  return (
    <div
      ref={rootRef}
      className={[`ui-ansc`, className].filter(Boolean).join(` `)}
      data-phase={phase}
      onMouseLeave={() => setHoveredSource(null)}
    >
      <style href={`ui-ai-answer-clean`} precedence={`default`}>
        {aiAnswerCleanStyles}
      </style>
      <div className={`ui-ansc__card`}>
        <div ref={cardRef} className={`ui-ansc__body`}>
          <div ref={innerRef} className={`ui-ansc__inner`}>
            {question && <h3 className={`ui-ansc__question`}>{question}</h3>}
            {sources.length > 0 && (
              <div
                className={`ui-ansc__sources`}
                aria-label={`Sources`}
                role={`list`}
                key={`s${runId}`}
              >
                {sources.map((e, t) => {
                  let n = (
                      <>
                        <span className={`ui-ansc__site`}>
                          {e.icon && <span className={`ui-ansc__favicon`}>{e.icon}</span>}
                          <span className={`ui-ansc__site-name`}>{e.name}</span>
                          <span className={`ui-ansc__num`}>{t + 1}</span>
                        </span>
                        <span className={`ui-ansc__title`}>{e.title}</span>
                      </>
                    ),
                    i = {
                      className: `ui-ansc__source`,
                      "data-lit": highlightedSources.has(t) || void 0,
                      style: {
                        animationDelay: skipAnimation ? `0ms` : `${120 + t * sourceStaggerMs}ms`,
                      },
                      onMouseEnter: () => setHoveredSource(t),
                      onMouseLeave: () => setHoveredSource(null),
                    };
                  return (
                    <div role={`listitem`} className={`ui-ansc__source-wrap`} key={t}>
                      {e.href ? (
                        <a {...i} href={e.href} target={`_blank`} rel={`noreferrer`}>
                          {n}
                        </a>
                      ) : (
                        <div {...i}>{n}</div>
                      )}
                    </div>
                  );
                })}
              </div>
            )}
            <div className={`ui-ansc__label`}>
              <AnswerSpark />
              <span
                className={
                  isFinished ? `ui-ansc__label-text` : `ui-ansc__label-text ui-ansc__shimmer`
                }
                data-text={phaseLabel}
                key={phaseLabel}
              >
                {phaseLabel}
              </span>
            </div>
            <div className={`ui-ansc__answer`} aria-busy={!isFinished}>
              {phase === `writing` && visibleTokens === 0 && (
                <p>
                  <span className={`ui-ansc__caret`} aria-hidden={`true`} />
                </p>
              )}
              {phase === `stopped` && visibleTokens === 0 && (
                <p className={`ui-ansc__empty`}>{`Stopped before answering.`}</p>
              )}
              {blocks.map((e, t) =>
                firstTokenIndex(e) >= visibleTokens ? null : e.kind === `p` ? (
                  <p key={`${runId}-${t}`}>{renderTokens(e.tokens)}</p>
                ) : (
                  <ul key={`${runId}-${t}`}>
                    {e.items.map((e, t) =>
                      e[0] && e[0].i < visibleTokens ? <li key={t}>{renderTokens(e)}</li> : null,
                    )}
                  </ul>
                ),
              )}
            </div>
            {phase === `done` && followUps.length > 0 && (
              <div className={`ui-ansc__follow`}>
                <span className={`ui-ansc__follow-label`}>{`Related`}</span>
                {followUps.map((e, t) => (
                  <button
                    type={`button`}
                    className={`ui-ansc__follow-item`}
                    style={{
                      animationDelay: `${skipAnimation ? 0 : 80 + t * 60}ms`,
                    }}
                    onClick={() => onFollowUp?.(e)}
                    key={e}
                  >
                    <span>{e}</span>
                    <CleanAnswerIcon d={iconPaths.chevron} solid={true} />
                  </button>
                ))}
              </div>
            )}
          </div>
        </div>
        <div className={`ui-ansc__foot`}>
          {isFinished ? (
            <div className={`ui-ansc__actions`} key={`actions`}>
              <button
                type={`button`}
                className={`ui-ansc__action`}
                aria-label={copied ? `Copied` : `Copy answer`}
                onClick={copyAnswer}
              >
                <CleanAnswerIcon
                  d={copied ? iconPaths.check : iconPaths.copy}
                  solid={true}
                  className={copied ? `ui-ansc__ok` : void 0}
                />
              </button>
              <button
                type={`button`}
                className={`ui-ansc__action ui-ansc__redo`}
                aria-label={`Regenerate`}
                onClick={regenerate}
              >
                <CleanAnswerIcon d={iconPaths.redo} />
              </button>
              <button
                type={`button`}
                className={`ui-ansc__action`}
                aria-label={`Good answer`}
                aria-pressed={feedback === `up`}
                onClick={() => toggleFeedback(`up`)}
              >
                <CleanAnswerIcon d={iconPaths.thumb} solid={true} />
              </button>
              <button
                type={`button`}
                className={`ui-ansc__action ui-ansc__down`}
                aria-label={`Bad answer`}
                aria-pressed={feedback === `down`}
                onClick={() => toggleFeedback(`down`)}
              >
                <CleanAnswerIcon d={iconPaths.thumb} solid={true} />
              </button>
            </div>
          ) : (
            <button type={`button`} className={`ui-ansc__stop`} onClick={stopAnswer} key={`stop`}>
              <span className={`ui-ansc__stop-icon`} aria-hidden={`true`} />
              {`Stop`}
            </button>
          )}
          {isFinished && (
            <span className={`ui-ansc__status`} aria-live={`polite`} key={statusLabel}>
              {statusLabel.startsWith(`Answered in `) ? (
                <>
                  <span className={`ui-ansc__status-lead`}>{`Answered in `}</span>
                  {statusLabel.slice(12)}
                </>
              ) : (
                statusLabel
              )}
            </span>
          )}
        </div>
        <div className={`ui-ansc__reasons`} data-open={feedback === `down` && !feedbackReason}>
          <div>
            {feedbackReasons.map((e) => (
              <button
                type={`button`}
                tabIndex={feedback === `down` && !feedbackReason ? 0 : -1}
                onClick={() => {
                  (setFeedbackReason(e), onFeedback?.(`down`, e));
                }}
                key={e}
              >
                {e}
              </button>
            ))}
          </div>
        </div>
      </div>
      {popover && (
        <div
          id={instanceId}
          role={`tooltip`}
          className={`ui-ansc__pop`}
          style={{
            left: popover.left,
            top: popover.top,
            width: popover.width,
          }}
          onMouseEnter={() => clearTimeout(hideTimerRef.current)}
          onMouseLeave={schedulePopoverClose}
        >
          {popover.ids.map((e) => {
            let n = sources[e];
            return (
              <a
                className={`ui-ansc__pop-item`}
                href={n.href}
                target={`_blank`}
                rel={`noreferrer`}
                tabIndex={-1}
                key={e}
              >
                <span className={`ui-ansc__site`}>
                  {n.icon && <span className={`ui-ansc__favicon`}>{n.icon}</span>}
                  <span className={`ui-ansc__site-name`}>
                    {n.href ? n.href.replace(/^https?:\/\/(www\.)?/, ``).split(`/`)[0] : n.name}
                  </span>
                  <span className={`ui-ansc__num`}>{e + 1}</span>
                </span>
                <span className={`ui-ansc__pop-title`}>{n.title}</span>
                {n.snippet && popover.ids.length === 1 && (
                  <span className={`ui-ansc__snippet`}>{n.snippet}</span>
                )}
              </a>
            );
          })}
        </div>
      )}
    </div>
  );
}
var prefersReducedMotion = () =>
  typeof window < `u` && window.matchMedia?.(`(prefers-reduced-motion: reduce)`).matches;
var aiAnswerCleanStyles = `
/* Colors and motion as variables – override them on .ui-ansc */
.ui-ansc {
  --ui-ansc-card: #ffffff;
  --ui-ansc-ink: rgba(0, 0, 0, 0.88);
  --ui-ansc-strong: #000000;
  --ui-ansc-text: rgba(0, 0, 0, 0.61);
  --ui-ansc-muted: rgba(0, 0, 0, 0.45);
  --ui-ansc-faint: rgba(0, 0, 0, 0.27);
  --ui-ansc-icon: rgba(0, 0, 0, 0.447);
  --ui-ansc-line: rgba(0, 0, 0, 0.06);
  --ui-ansc-fill: rgba(0, 0, 0, 0.06);
  --ui-ansc-fill-strong: rgba(0, 0, 0, 0.1);
  --ui-ansc-wash: rgba(0, 0, 0, 0.015);
  --ui-ansc-accent: rgba(0, 96, 226, 0.765);
  --ui-ansc-ok: #1a9a52;
  --ui-ansc-shine: rgba(255, 255, 255, 0.82);
  /* Strokes are shadows: a 0.5px hairline plus a soft lift */
  --ui-ansc-shadow: 0 0 0 0.5px rgba(0, 0, 0, 0.06), 0 1px 1px -1px rgba(0, 0, 0, 0.1), 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --ui-ansc-shadow-pop: 0 0 0 0.5px rgba(0, 0, 0, 0.08), 0 12px 28px -10px rgba(0, 0, 0, 0.16), 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --ui-ansc-focus: rgba(0, 96, 226, 0.35);
  --ui-ansc-ease: cubic-bezier(0.22, 1, 0.36, 1);
  position: relative;
  box-sizing: border-box;
  container-type: inline-size;
  display: grid;
  width: 100%;
  max-width: 640px;
  font-family: "Inter", "InterVariable", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 13px;
  line-height: 20px;
  font-weight: 400;
  color: var(--ui-ansc-ink);
  -webkit-font-smoothing: antialiased;
}
.ui-ansc *, .ui-ansc *::before, .ui-ansc *::after { box-sizing: border-box; }
:where(.ui-ansc) button { margin: 0; padding: 0; border: 0; background: none; font: inherit; color: inherit; cursor: pointer; }
:where(.ui-ansc) svg { display: block; flex: none; }
.ui-ansc button:focus-visible, .ui-ansc a:focus-visible { outline: 2px solid var(--ui-ansc-focus); outline-offset: 1px; }

/* One white card – the edge is a shadow, not a border */
.ui-ansc__card {
  overflow: hidden;
  border-radius: 10px;
  background: var(--ui-ansc-card);
  box-shadow: var(--ui-ansc-shadow);
}
.ui-ansc__body { overflow: hidden; transition: height 360ms var(--ui-ansc-ease); }
.ui-ansc__inner { display: flow-root; padding: 20px 20px 16px; }
.ui-ansc__question { margin: 0 0 14px; font-size: 15px; font-weight: 500; line-height: 24px; color: var(--ui-ansc-strong); }

/* Sources: small white cards in a row that scrolls sideways */
.ui-ansc__sources {
  display: flex;
  gap: 8px;
  margin: 0 -20px;
  padding: 2px 20px 4px;
  overflow-x: auto;
  scroll-padding: 0 20px;
  scrollbar-width: none;
  -webkit-mask: linear-gradient(90deg, transparent, transparent 6px, #000 20px, #000 calc(100% - 120px), transparent calc(100% - 20px));
  mask: linear-gradient(90deg, transparent, transparent 6px, #000 20px, #000 calc(100% - 120px), transparent calc(100% - 20px));
}
.ui-ansc__sources::-webkit-scrollbar { display: none; }
.ui-ansc__source-wrap { flex: none; display: flex; }
.ui-ansc__source {
  display: flex;
  flex-direction: column;
  gap: 4px;
  width: 168px;
  padding: 8px 10px 9px;
  border-radius: 8px;
  background: var(--ui-ansc-card);
  box-shadow: var(--ui-ansc-shadow);
  color: inherit;
  text-decoration: none;
  transition: background-color 160ms ease, box-shadow 200ms ease;
  animation: ui-ansc-card 460ms var(--ui-ansc-ease) both;
}
a.ui-ansc__source:hover { background: var(--ui-ansc-wash); }
.ui-ansc__source[data-lit] { background: var(--ui-ansc-wash); box-shadow: 0 0 0 0.5px rgba(0, 0, 0, 0.1), 0 1px 1px -1px rgba(0, 0, 0, 0.1), 0 1px 2px 0 rgba(0, 0, 0, 0.05); }
.ui-ansc__site { display: flex; align-items: center; gap: 6px; min-width: 0; font-size: 12px; line-height: 16px; color: var(--ui-ansc-text); }
.ui-ansc__site-name { flex: 1; min-width: 0; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
.ui-ansc__num { flex: none; font-size: 10px; line-height: 16px; font-weight: 500; letter-spacing: 0.5px; font-variant-numeric: tabular-nums; color: var(--ui-ansc-faint); }
.ui-ansc__favicon {
  display: grid;
  flex: none;
  width: 14px;
  height: 14px;
  overflow: hidden;
  border-radius: 4px;
  box-shadow: 0 0 0 0.5px rgba(0, 0, 0, 0.1);
}
.ui-ansc__favicon svg { width: 100%; height: 100%; }
.ui-ansc__title {
  display: -webkit-box;
  overflow: hidden;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  font-size: 13px;
  font-weight: 500;
  line-height: 20px;
  color: var(--ui-ansc-strong);
}

/* "Reading 6 sources" → "Writing" → "Answer" */
.ui-ansc__label { display: flex; align-items: center; gap: 6px; margin: 16px 0 6px; font-size: 12px; line-height: 16px; color: var(--ui-ansc-text); }
.ui-ansc__mark { width: 16px; height: 16px; fill: var(--ui-ansc-accent); overflow: visible; }
.ui-ansc__mark path { transform-box: fill-box; transform-origin: center; }
/* While it works the big sparkle breathes and the small one twinkles */
.ui-ansc[data-phase="reading"] .ui-ansc__mark-big,
.ui-ansc[data-phase="writing"] .ui-ansc__mark-big { animation: ui-ansc-breathe 1.4s ease-in-out infinite; }
