.ui-ansc__action:has(.ui-ansc__ok) { color: var(--ui-ansc-ok); }
.ui-ansc__status { font-size: 12px; line-height: 16px; white-space: nowrap; color: var(--ui-ansc-muted); animation: ui-ansc-fade 260ms var(--ui-ansc-ease) both; }
@container (max-width: 330px) {
