  .ui-ansc__foot { height: 52px; }
  .ui-ansc__stop { height: 34px; }
  .ui-ansc__reasons button { height: 34px; padding: 0 12px; }
  .ui-ansc__follow-item { min-height: 44px; }
  .ui-ansc__cite { position: relative; }
